use derive_more::Display;
use std::str::FromStr;
use thiserror::Error;

/// The opaque text form of a stable instance identifier generated by its driver.
///
/// Identifiers are non-empty and contain no whitespace or control characters.
/// Values are preserved exactly without assuming a UUID or numeric format.
/// The owning driver resolves the identifier to its instance configuration row.
#[derive(Clone, Debug, Display, Eq, Hash, PartialEq)]
pub struct InstanceId(String);

#[derive(Clone, Copy, Debug, Error, Eq, PartialEq)]
pub enum InstanceIdError {
    #[error("instance identifiers cannot be empty")]
    Empty,
    #[error("instance identifiers cannot contain whitespace or control characters")]
    InvalidCharacter,
}

impl InstanceId {
    pub fn parse(input: &str) -> Result<Self, InstanceIdError> {
        if input.is_empty() {
            return Err(InstanceIdError::Empty);
        }
        if input
            .chars()
            .any(|ch| ch.is_whitespace() || ch.is_control())
        {
            return Err(InstanceIdError::InvalidCharacter);
        }
        Ok(Self(input.into()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl FromStr for InstanceId {
    type Err = InstanceIdError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        Self::parse(input)
    }
}

impl TryFrom<String> for InstanceId {
    type Error = InstanceIdError;

    fn try_from(input: String) -> Result<Self, Self::Error> {
        Self::parse(&input)
    }
}

#[derive(ah_id::Id)]
#[id(generate, display)]
struct GeneratedInstanceId(ah_id::UuidV7);
/// Generate the host/default driver's UUIDv7 identity without constraining custom IDs.
pub fn new_instance_id() -> Result<InstanceId, super::DriverError> {
    InstanceId::parse(&GeneratedInstanceId::new().to_string()).map_err(|source| {
        super::StorageError::with_source(super::StorageErrorKind::InvalidData, source).into()
    })
}
